// Checks the docs in docs/ and regenerates their indexes.
//
//   npm run docs:check   validate IDs, front matter and traces; fail if a generated file is out of date
//   npm run docs:build   same checks, then rewrite the generated files
//
// How IDs work is explained in docs/README.md. Problems that block a PR are errors (exit 1). Gaps that are
// normal while work is in progress (a criterion with no test yet, a test with no tag) are only reported in the
// generated docs/traceability/ files and printed as warnings.
import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as prettier from 'prettier';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const DOCS = join(ROOT, 'docs');
const TESTS = join(ROOT, 'e2e', 'tests');
const WRITE = process.argv.includes('--write');

const ID_PATTERN =
  /\b(?:(?:US|BR|AC|NFR|MSG|Q|SCR|FLW|API|DD|TCO|MTC|RSK|TP|TCR)-[A-Z][A-Z0-9]*-\d{2,}|ADR-\d{4})\b/g;
const STATUSES = [
  'draft',
  'review',
  'approved',
  'deprecated',
  'proposed',
  'accepted',
  'superseded',
];
// Columns each kind of doc must have in its main table (the table whose first header is "ID" or "Column"),
// and the values allowed in them: a list, `TEXT` (any non-empty text) or `OPTIONAL`. See docs/STANDARDS.md.
const TEXT = 'text';
const OPTIONAL = 'optional';
const PRIORITIES = ['Must', 'Should', 'Could', "Won't"];
const RISKS = ['High', 'Medium', 'Low'];
const VERIFY = ['Auto-UI', 'Auto-API', 'Unit', 'Manual', 'Review'];
const ROW_STATUSES = ['proposed', 'approved', 'deprecated'];
const QUALITY = [
  'Functional suitability',
  'Performance efficiency',
  'Compatibility',
  'Interaction capability',
  'Reliability',
  'Security',
  'Maintainability',
  'Flexibility',
  'Safety',
];
const TECHNIQUES = [
  'Equivalence partitioning',
  'Boundary value analysis',
  'Decision table',
  'State transition',
  'Use case',
  'Pairwise',
  'Error guessing',
  'Exploratory',
];
const MULTI = new Set(['Verify', 'Mitigated by', 'Traces', 'Covers']);
const COLUMNS = {
  stories: { Priority: PRIORITIES, Source: TEXT, Status: ROW_STATUSES },
  rules: { Source: TEXT, Status: ROW_STATUSES },
  acceptance: { Covers: TEXT, Priority: PRIORITIES, Risk: RISKS, Verify: VERIFY },
  nfr: {
    'Quality characteristic': QUALITY,
    Measure: TEXT,
    Priority: PRIORITIES,
    Verify: VERIFY,
    Source: TEXT,
  },
  messages: {
    Kind: ['error', 'warning', 'info', 'success'],
    'Shown as': ['field', 'alert', 'status', 'toast', 'page', 'api'],
  },
  table: { Definition: TEXT, Classification: ['public', 'internal', 'personal', 'secret'] },
  'test-conditions': { Technique: TECHNIQUES, Traces: TEXT, Priority: PRIORITIES },
  risks: {
    Likelihood: RISKS,
    Impact: RISKS,
    Level: RISKS,
    'Mitigated by': OPTIONAL,
    Status: ['open', 'mitigated', 'accepted', 'closed'],
  },
};
// Sections (`## Heading`) each kind of doc must have.
const SECTIONS = {
  feature: [
    'Goal',
    'Stakeholders',
    'Actors',
    'Assumptions and constraints',
    'Dependencies',
    'Out of scope',
    'Business risks',
    'Open questions',
    'Change log',
  ],
  screen: [
    'Layout',
    'Actions',
    'States',
    'Permissions',
    'Accessibility',
    'Responsive',
    'Locators for tests',
    'Change log',
  ],
  flow: [
    'Actors',
    'Preconditions',
    'Postconditions',
    'Diagram',
    'Main flow',
    'Alternative flows',
    'Exception flows',
    'Change log',
  ],
  'detail-design': ['Errors', 'Security', 'Testability', 'Change log'],
  api: ['Request', 'Responses', 'Security', 'Side effects', 'Test ideas', 'Change log'],
  table: [
    'Columns',
    'Indexes and constraints',
    'Relationships',
    'Lifecycle',
    'Retention',
    'Data quality rules',
    'Seed data',
    'Used by',
    'Change log',
  ],
  decision: [
    'Context and problem',
    'Decision drivers',
    'Considered options',
    'Decision outcome',
    'Pros and cons of the options',
  ],
  'test-plan': [
    'Scope',
    'Product risks',
    'Approach',
    'Entry criteria',
    'Exit criteria',
    'Change log',
  ],
  'test-report': ['Summary', 'Coverage', 'Results', 'Defects', 'Exit criteria', 'Residual risks'],
};
// ADRs before this number were written before MADR and keep their original shape.
const FIRST_MADR_ADR = 8;
const VIEWPOINTS = ['interaction', 'state', 'algorithm', 'information', 'interface', 'composition'];
const GENERATED = {
  requirements: 'requirements/README.md',
  decisions: 'decisions/README.md',
};
const TRACEABILITY_DIR = 'traceability';
const GENERATED_NOTE = '<!-- Generated by `npm run docs:build`. Do not edit by hand. -->';

const errors = [];
const posix = (path) => path.split(sep).join('/');
const typeOf = (id) => id.split('-')[0];

async function walk(dir, ext) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name !== 'node_modules') out.push(...(await walk(path, ext)));
    } else if (entry.name.endsWith(ext)) {
      out.push(path);
    }
  }
  return out;
}

// Minimal front matter parser: `key: value`, `key: [a, b]` and one level of nesting.
// Prettier wraps long `[a, b]` lists over several lines, so those are joined back into one line first.
function parseFrontMatter(text) {
  const match = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (!match) return null;
  const body = match[1]
    .replace(/\[[^\]]*\]/g, (list) => list.replace(/\s*\n\s*/g, ' '))
    .replace(/:[ \t]*\n\s*\[/g, ': [');
  const data = {};
  let parent = null;
  for (const raw of body.split('\n')) {
    const line = raw.replace(/\s+#.*$/, '');
    if (!line.trim()) continue;
    const kv = line.match(/^(\s*)([\w-]+):\s*(.*)$/);
    if (!kv) continue;
    const [, indent, key, rawValue] = kv;
    const value = rawValue.startsWith('[')
      ? rawValue
          .replace(/^\[|\]$/g, '')
          .split(',')
          .map((v) => v.trim())
          .filter(Boolean)
      : rawValue.trim();
    if (indent && parent) {
      data[parent][key] = value;
    } else if (value === '') {
      parent = key;
      data[key] = {};
    } else {
      parent = null;
      data[key] = value;
    }
  }
  return data;
}

// Which docs must have front matter, and which keys they need.
// Every doc also names its owner and reviewers (ISO/IEC/IEEE 15289).
function requiredKeys(rel) {
  const review = ['owner', 'reviewers'];
  if (/^requirements\/[^/]+\/[^/]+\.md$/.test(rel))
    return ['title', 'type', 'feature', 'status', ...review];
  if (rel.startsWith('design/detail/'))
    return ['id', 'title', 'type', 'feature', 'viewpoint', 'status', ...review];
  if (rel.startsWith('design/')) return ['id', 'title', 'type', 'feature', 'status', ...review];
  if (/^decisions\/ADR-/.test(rel)) return ['id', 'title', 'type', 'status', ...review];
  if (/^api\/[^/]+\/[^/]+\.md$/.test(rel))
    return ['id', 'title', 'type', 'feature', 'status', ...review];
  if (/^database\/tables\/[^/]+\.md$/.test(rel)) return ['title', 'type', 'status', ...review];
  if (rel.startsWith('testing/')) return ['title', 'type', 'status', ...review];
  return null;
}

const docs = [];
for (const path of await walk(DOCS, '.md')) {
  const rel = posix(relative(DOCS, path));
  if (
    rel.startsWith('_templates/') ||
    rel.startsWith(`${TRACEABILITY_DIR}/`) ||
    Object.values(GENERATED).includes(rel)
  )
    continue;
  const text = await readFile(path, 'utf8');
  docs.push({ rel, text, meta: parseFrontMatter(text) });
}

// 1. Front matter
for (const doc of docs) {
  const keys = requiredKeys(doc.rel);
  if (!keys) continue;
  if (!doc.meta) {
    errors.push(`docs/${doc.rel}: missing front matter`);
    continue;
  }
  for (const key of keys.filter((k) => k !== 'reviewers')) {
    if (!doc.meta[key]) errors.push(`docs/${doc.rel}: front matter needs "${key}"`);
  }
  if (
    keys.includes('reviewers') &&
    !(Array.isArray(doc.meta.reviewers) && doc.meta.reviewers.length)
  ) {
    errors.push(`docs/${doc.rel}: front matter needs "reviewers: [name]"`);
  }
  if (['approved', 'accepted'].includes(doc.meta.status) && typeof doc.meta.approved !== 'string') {
    errors.push(
      `docs/${doc.rel}: status is ${doc.meta.status}, so front matter needs "approved: YYYY-MM-DD"`,
    );
  }
  if (doc.meta.viewpoint && !VIEWPOINTS.includes(doc.meta.viewpoint)) {
    errors.push(
      `docs/${doc.rel}: unknown viewpoint "${doc.meta.viewpoint}" (use ${VIEWPOINTS.join(', ')})`,
    );
  }
  const headings = new Set([...doc.text.matchAll(/^## (.+)$/gm)].map((m) => m[1].trim()));
  const madr = doc.meta.type !== 'decision' || Number(doc.meta.id?.split('-')[1]) >= FIRST_MADR_ADR;
  for (const section of madr ? (SECTIONS[doc.meta.type] ?? []) : []) {
    if (![...headings].some((h) => h === section || h.startsWith(`${section} `))) {
      errors.push(`docs/${doc.rel}: needs a "## ${section}" section (see docs/_templates/)`);
    }
  }
  if (doc.meta.status && !STATUSES.includes(doc.meta.status)) {
    errors.push(
      `docs/${doc.rel}: unknown status "${doc.meta.status}" (use ${STATUSES.join(', ')})`,
    );
  }
  if (
    doc.meta.id &&
    !doc.rel.split('/').pop().startsWith(`${doc.meta.id}-`) &&
    doc.meta.type !== 'api'
  ) {
    errors.push(`docs/${doc.rel}: file name should start with its id "${doc.meta.id}-"`);
  }
}

// 2. Definitions: a front matter id, or the first cell of a table row in a doc with front matter.
//    A table row also keeps its cells by column name (`cols`), so Priority, Risk, Verify, Covers... can be read.
const defs = new Map(); // id -> { rel, line, doc, row, cols }
const splitRow = (line) =>
  line
    .split(/(?<!\\)\|/)
    .slice(1, -1)
    .map((c) => c.trim());
const isSeparator = (line) => /^\|(\s*:?-+:?\s*\|)+\s*$/.test(line ?? '');
function define(id, rel, line, extra) {
  const existing = defs.get(id);
  if (existing) {
    errors.push(
      `docs/${rel}:${line}: ${id} is already defined in docs/${existing.rel}:${existing.line}`,
    );
    return;
  }
  defs.set(id, { rel, line, ...extra });
}
for (const doc of docs) {
  if (!doc.meta) continue;
  if (doc.meta.id) define(doc.meta.id, doc.rel, 1, { doc });
  const lines = doc.text.split('\n');
  let header = [];
  lines.forEach((line, i) => {
    if (line.trim()[0] !== '|' || isSeparator(line)) return;
    const cells = splitRow(line.trim());
    if (isSeparator(lines[i + 1])) {
      header = cells;
      return;
    }
    const first = cells[0];
    if (first?.match(ID_PATTERN)?.[0] === first) {
      const cols = Object.fromEntries(header.map((name, k) => [name, cells[k] ?? '']));
      define(first, doc.rel, i + 1, { doc, row: cells.slice(1), cols });
    }
  });
}

// 2b. Columns: the main table of each kind of doc has its required columns, with allowed values.
const listOf = (value) =>
  (value ?? '')
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean);
for (const doc of docs) {
  const required = COLUMNS[doc.meta?.type];
  if (!required) continue;
  const lines = doc.text.split('\n');
  let header = null;
  let headerLine = 0;
  lines.forEach((line, i) => {
    if (line.trim()[0] !== '|') {
      header = null;
      return;
    }
    if (isSeparator(line)) return;
    const cells = splitRow(line.trim());
    if (isSeparator(lines[i + 1])) {
      const main = cells[0] === 'ID' || (cells[0] === 'Column' && cells.includes('Type'));
      header = main ? cells : null;
      headerLine = i + 1;
      if (header) {
        for (const column of Object.keys(required)) {
          if (!header.includes(column)) {
            errors.push(`docs/${doc.rel}:${headerLine}: table needs a "${column}" column`);
          }
        }
      }
      return;
    }
    if (!header) return;
    const name = cells[0];
    for (const [column, allowed] of Object.entries(required)) {
      const k = header.indexOf(column);
      if (k < 0 || allowed === OPTIONAL) continue;
      const values = MULTI.has(column) ? listOf(cells[k]) : [cells[k]].filter(Boolean);
      if (!values.length) {
        errors.push(`docs/${doc.rel}:${i + 1}: ${name} needs a "${column}" value`);
        continue;
      }
      if (allowed === TEXT) continue;
      for (const value of values) {
        if (!allowed.includes(value)) {
          errors.push(
            `docs/${doc.rel}:${i + 1}: ${name} has ${column} "${value}" (use ${allowed.join(', ')})`,
          );
        }
      }
    }
  });
}

// 3. References in docs and traces must point to something defined.
for (const doc of docs) {
  doc.text.split('\n').forEach((line, i) => {
    for (const id of line.match(ID_PATTERN) ?? []) {
      if (!defs.has(id)) errors.push(`docs/${doc.rel}:${i + 1}: ${id} is not defined anywhere`);
    }
  });
}

// 4. Reverse traces: which design/API docs point at each id.
const tracedBy = new Map(); // id -> [doc]
for (const doc of docs) {
  if (!doc.meta?.id || typeof doc.meta.traces !== 'object') continue;
  for (const ids of Object.values(doc.meta.traces)) {
    for (const id of Array.isArray(ids) ? ids : []) {
      if (!tracedBy.has(id)) tracedBy.set(id, []);
      tracedBy.get(id).push(doc);
    }
  }
}

// 5. Playwright tests and tags: `@AC-AUTH-02` in e2e/tests.
//    testsFor: forward view (id -> where it is tagged). testCases: reverse view (each test -> its tags).
const testsFor = new Map(); // id -> ['e2e/tests/...:line']
const testCases = []; // { rel, line, title, ids, tagFromData }
const TAG = /@((?:[A-Z]+-[A-Z][A-Z0-9]*-\d{2,}))\b/g;
const TEST_CALL =
  /(?<![.\w])test(?:\.(?:only|skip|fixme|fail))?\(\s*(['"`])((?:\\.|(?!\1)[\s\S])*?)\1\s*,([\s\S]*?)(?=\basync\b|=>|\bfunction\b)/g;
const lineAt = (text, index) => text.slice(0, index).split('\n').length;
for (const path of await walk(TESTS, '.ts')) {
  const rel = posix(relative(ROOT, path));
  const text = await readFile(path, 'utf8');
  const inTestHeader = new Set(); // lines that belong to a test( ... header
  if (!rel.endsWith('.setup.ts')) {
    for (const match of text.matchAll(TEST_CALL)) {
      const [, , title, options] = match;
      const line = lineAt(text, match.index);
      const end = lineAt(text, match.index + match[0].length);
      for (let l = line; l <= end; l++) inTestHeader.add(l);
      const ids = [...options.matchAll(TAG)].map((m) => m[1]);
      testCases.push({
        rel,
        line,
        title: title.replace(/\s+/g, ' '),
        ids,
        tagFromData: !ids.length && /\btag\s*:/.test(options),
      });
    }
    // A tag outside a test( ... header is in a test data table (a data-driven test).
    text.split('\n').forEach((line, i) => {
      if (inTestHeader.has(i + 1)) return;
      const ids = [...line.matchAll(TAG)].map((m) => m[1]);
      if (ids.length) testCases.push({ rel, line: i + 1, title: null, ids, tagFromData: false });
    });
  }
  text.split('\n').forEach((line, i) => {
    for (const [, id] of line.matchAll(TAG)) {
      if (!defs.has(id)) {
        errors.push(`${rel}:${i + 1}: tag @${id} does not match any requirement ID`);
        continue;
      }
      if (!testsFor.has(id)) testsFor.set(id, []);
      testsFor.get(id).push(`${rel}:${i + 1}`);
    }
  });
}

// 6. Messages: every MSG row in docs/requirements has the same text in packages/shared/src/messages.ts,
//    and no app file copies a message string instead of using msg().
const MESSAGES_FILE = join(ROOT, 'packages', 'shared', 'src', 'messages.ts');
const MESSAGES_REL = posix(relative(ROOT, MESSAGES_FILE));
const MSG_ENTRY = /'(MSG-[A-Z][A-Z0-9]*-\d{2,})':\s*(['"])((?:\\.|(?!\2)[^\\])*)\2/g;
const codeMessages = new Map(); // id -> { text, rel }
for (const [, id, , raw] of (await readFile(MESSAGES_FILE, 'utf8')).matchAll(MSG_ENTRY)) {
  codeMessages.set(id, { text: raw.replace(/\\(.)/g, '$1'), rel: MESSAGES_REL });
}
for (const [id, def] of defs) {
  if (typeOf(id) !== 'MSG') continue;
  const docText = (def.row ?? []).filter(Boolean).at(-1)?.replace(/\\\|/g, '|');
  const code = codeMessages.get(id);
  if (!code) {
    errors.push(`docs/${def.rel}:${def.line}: ${id} is missing from ${MESSAGES_REL}`);
  } else if (code.text !== docText) {
    errors.push(
      `docs/${def.rel}:${def.line}: ${id} text differs from ${code.rel}\n    docs: ${docText}\n    code: ${code.text}`,
    );
  }
}
for (const [id, code] of codeMessages) {
  if (!defs.has(id))
    errors.push(`${code.rel}: ${id} is not in any docs/requirements/*/messages.md`);
}
for (const app of ['api', 'web']) {
  for (const path of await walk(join(ROOT, 'apps', app, 'src'), '')) {
    if (!/\.tsx?$/.test(path) || /\.test\.tsx?$/.test(path)) continue;
    const rel = posix(relative(ROOT, path));
    if (rel.includes('/generated/')) continue;
    const text = await readFile(path, 'utf8');
    for (const [id, code] of codeMessages) {
      // The longest fixed part between {placeholders}: "Release " alone is too common to flag.
      const literal = code.text
        .split(/\{\w+\}/)
        .reduce((a, b) => (b.length > a.length ? b : a), '');
      if (literal.length >= 8 && text.includes(literal)) {
        errors.push(`${rel}: copies the text of ${id}; use msg('${id}') instead`);
      }
    }
  }
}

// 6b. Permissions: the matrix in docs/requirements/project/README.md (BR-PROJECT-35) and the PERMISSIONS map of
//     packages/shared/src/permissions.ts list the same actions in the same order and allow the same roles.
const PERMISSIONS_REL = 'packages/shared/src/permissions.ts';
const MATRIX_REL = 'requirements/project/README.md';
const MATRIX_ROLES = [
  'OWNER',
  'PROJECT_MANAGER',
  'QA_LEAD',
  'QA_ENGINEER',
  'TEAM_LEAD',
  'DEVELOPER',
  'STAKEHOLDER',
  'VIEWER',
];
const codePermissions = [
  ...(await readFile(join(ROOT, PERMISSIONS_REL), 'utf8')).matchAll(
    /^\s*'([a-z-]+:[a-z-]+)':\s*\[([^\]]*)\]/gm,
  ),
].map(([, action, list]) => ({
  action,
  roles: [...list.matchAll(/'([A-Z_]+)'/g)].map((m) => m[1]),
}));
const matrixText =
  (await readFile(join(DOCS, MATRIX_REL), 'utf8')).split(/^### Permission matrix$/m)[1] ?? '';
const matrixRows = matrixText
  .split('\n')
  .filter((line) => /^\|.*(✅|❌)/.test(line))
  .map((line) => {
    const cells = line
      .split('|')
      .slice(1, -1)
      .map((c) => c.trim());
    return { label: cells[0], cells: cells.slice(1, 1 + MATRIX_ROLES.length) };
  })
  // A row with a footnote (✅¹, "Leave the project") is a rule the services check by hand, not a map entry.
  .filter((row) => row.cells.every((cell) => cell === '✅' || cell === '❌'))
  .map((row) => ({
    label: row.label,
    roles: MATRIX_ROLES.filter((_, i) => row.cells[i] === '✅'),
  }));
if (matrixRows.length !== codePermissions.length) {
  errors.push(
    `docs/${MATRIX_REL}: the permission matrix has ${matrixRows.length} rows, ${PERMISSIONS_REL} has ${codePermissions.length} actions`,
  );
} else {
  codePermissions.forEach(({ action, roles }, i) => {
    const row = matrixRows[i];
    if (row.roles.join() !== roles.join())
      errors.push(
        `docs/${MATRIX_REL}: matrix row "${row.label}" allows ${row.roles.join(', ')}; ${PERMISSIONS_REL} '${action}' allows ${roles.join(', ')}`,
      );
  });
}

// 7. Generated files
const idsOfType = (type, feature) =>
  [...defs.keys()]
    .filter((id) => typeOf(id) === type && (!feature || id.split('-')[1] === feature))
    .sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));
const linkTo = (fromRel, id) => {
  const def = defs.get(id);
  const target = posix(relative(dirname(join(DOCS, fromRel)), join(DOCS, def.rel)));
  return `[${id}](${target})`;
};
const cell = (items) => (items.length ? items.join(', ') : '—');
const features = docs
  .filter((d) => /^requirements\/[^/]+\/README\.md$/.test(d.rel) && d.meta)
  .map((d) => ({ ...d.meta, dir: d.rel.split('/')[1], code: d.rel.split('/')[1].toUpperCase() }))
  .sort((a, b) => Number(a.phase) - Number(b.phase) || a.dir.localeCompare(b.dir));

// Requirement attributes and links used by the traceability files.
const col = (id, name) => defs.get(id)?.cols?.[name] ?? '';
const verifyOf = (id) => listOf(col(id, 'Verify'));
const isAutomated = (id) => verifyOf(id).some((v) => v.startsWith('Auto-'));
const RISK_ORDER = Object.fromEntries(RISKS.map((r, i) => [r, i]));
const PRIORITY_ORDER = Object.fromEntries(PRIORITIES.map((p, i) => [p, i]));
const byRisk = (a, b) =>
  (RISK_ORDER[col(a, 'Risk')] ?? 9) - (RISK_ORDER[col(b, 'Risk')] ?? 9) ||
  (PRIORITY_ORDER[col(a, 'Priority')] ?? 9) - (PRIORITY_ORDER[col(b, 'Priority')] ?? 9) ||
  a.localeCompare(b, 'en', { numeric: true });
const coversOf = (id) => {
  const def = defs.get(id);
  const source = def.cols?.Covers ?? (def.row ?? []).join(' ');
  return [...new Set(source.match(ID_PATTERN) ?? [])].filter((ref) =>
    ['US', 'BR'].includes(typeOf(ref)),
  );
};
const withoutCriterion = (f) => {
  const covered = new Set(idsOfType('AC', f.code).flatMap(coversOf));
  return [...idsOfType('US', f.code), ...idsOfType('BR', f.code)].filter((id) => !covered.has(id));
};
const automationGaps = (f) =>
  idsOfType('AC', f.code)
    .filter((id) => isAutomated(id) && !testsFor.has(id))
    .sort(byRisk);
const untaggedTests = () =>
  testCases.filter((t) => t.title !== null && !t.ids.length && !t.tagFromData);
const testRef = (t) => `\`${t.replace('e2e/tests/', '')}\``;
const featureFile = (f) => `${TRACEABILITY_DIR}/${f.dir}.md`;
const tracedFeatures = () =>
  features.filter((f) => ['AC', 'US', 'NFR'].some((type) => idsOfType(type, f.code).length));

function traceabilityFeature(f) {
  const rel = featureFile(f);
  const acs = idsOfType('AC', f.code);
  const tested = acs.filter((id) => testsFor.has(id)).length;
  const gaps = automationGaps(f);
  const out = [
    GENERATED_NOTE,
    '',
    `# Traceability: ${f.title}`,
    '',
    `Back to the [overview](README.md). Requirements: [../requirements/${f.dir}/](../requirements/${f.dir}/README.md).`,
    '',
    `${acs.length} acceptance criteria, ${tested} with a tagged test, ${gaps.length} planned for automation without a test yet.`,
    '',
    '## Matrix',
    '',
    'Requirement → design → API → test. **Tests** lists where a test is tagged with the criterion; ⚠ means the',
    'criterion should be automated (Verify) but no test is tagged yet.',
    '',
    '| AC | Priority | Risk | Verify | Covers | Screens and flows | Detail design | API | Tests |',
    '| -- | -------- | ---- | ------ | ------ | ----------------- | ------------- | --- | ----- |',
  ];
  for (const id of acs) {
    const by = (types) =>
      (tracedBy.get(id) ?? [])
        .filter((d) => types.includes(typeOf(d.meta.id)))
        .map((d) => linkTo(rel, d.meta.id));
    const tests = (testsFor.get(id) ?? []).map(testRef);
    const testCell = tests.length ? tests.join(', ') : isAutomated(id) ? '⚠ none' : '—';
    out.push(
      `| ${linkTo(rel, id)} | ${col(id, 'Priority')} | ${col(id, 'Risk')} | ${col(id, 'Verify')} | ${cell(coversOf(id))} | ${cell(by(['SCR', 'FLW']))} | ${cell(by(['DD']))} | ${cell(by(['API']))} | ${testCell} |`,
    );
  }
  out.push(
    '',
    '## Automation gaps, highest risk first',
    '',
    'Criteria whose Verify says Auto-UI or Auto-API but no test is tagged with them yet. Start at the top.',
    '',
  );
  if (gaps.length) {
    out.push(
      '| AC | Risk | Priority | Verify | Then |',
      '| -- | ---- | -------- | ------ | ---- |',
    );
    for (const id of gaps) {
      out.push(
        `| ${linkTo(rel, id)} | ${col(id, 'Risk')} | ${col(id, 'Priority')} | ${col(id, 'Verify')} | ${col(id, 'Then')} |`,
      );
    }
  } else {
    out.push('None.');
  }
  const nfrs = idsOfType('NFR', f.code);
  out.push('', '## Non-functional requirements', '');
  if (nfrs.length) {
    out.push(
      '| NFR | Quality characteristic | Measure | Priority | Verify | Tests |',
      '| --- | ---------------------- | ------- | -------- | ------ | ----- |',
    );
    for (const id of nfrs) {
      const tests = (testsFor.get(id) ?? []).map(testRef);
      const testCell = tests.length ? tests.join(', ') : isAutomated(id) ? '⚠ none' : '—';
      out.push(
        `| ${linkTo(rel, id)} | ${col(id, 'Quality characteristic')} | ${col(id, 'Measure')} | ${col(id, 'Priority')} | ${col(id, 'Verify')} | ${testCell} |`,
      );
    }
  } else {
    out.push('None.');
  }
  const notAutomated = acs.filter((id) => !isAutomated(id));
  out.push(
    '',
    '## Checked without Playwright',
    '',
    'Criteria verified by unit tests, manual testing or review instead of a Playwright test.',
    '',
  );
  if (notAutomated.length) {
    out.push('| AC | Verify | Risk | Then |', '| -- | ------ | ---- | ---- |');
    for (const id of notAutomated) {
      out.push(
        `| ${linkTo(rel, id)} | ${col(id, 'Verify')} | ${col(id, 'Risk')} | ${col(id, 'Then')} |`,
      );
    }
  } else {
    out.push('None.');
  }
  const missing = withoutCriterion(f);
  out.push('', '## Stories and rules without an acceptance criterion', '');
  out.push(missing.length ? missing.map((id) => `- ${linkTo(rel, id)}`).join('\n') : 'None.', '');
  return out.join('\n');
}

function traceabilityTests() {
  const out = [
    GENERATED_NOTE,
    '',
    '# Traceability: tests → requirements',
    '',
    'The reverse view: every Playwright test and the requirement IDs it is tagged with. Back to the',
    '[overview](README.md).',
    '',
    'A data-driven test takes its tag from a test data row, so the row is listed with its own line.',
    '',
  ];
  const files = [...new Set(testCases.map((t) => t.rel))].sort();
  for (const file of files) {
    out.push(
      `## \`${file.replace('e2e/tests/', '')}\``,
      '',
      '| Line | Test | Requirements |',
      '| ---- | ---- | ------------ |',
    );
    for (const t of testCases.filter((c) => c.rel === file).sort((a, b) => a.line - b.line)) {
      const title = t.title === null ? '_test data row_' : t.title.replace(/\|/g, '\\|');
      const ids = t.ids.length
        ? t.ids
            .filter((id) => defs.has(id))
            .map((id) => linkTo(`${TRACEABILITY_DIR}/tests.md`, id))
            .join(', ')
        : t.tagFromData
          ? 'from test data rows'
          : '⚠ no tag';
      out.push(`| ${t.line} | ${title} | ${ids} |`);
    }
    out.push('');
  }
  return out.join('\n');
}

function traceabilityOverview() {
  const rel = `${TRACEABILITY_DIR}/README.md`;
  const out = [
    GENERATED_NOTE,
    '',
    '# Traceability',
    '',
    'How each requirement is designed, built and tested, following ISO/IEC/IEEE 29148 (requirement attributes,',
    'two-way traces) and ISTQB (test basis ↔ test ↔ result). Edit the source docs, never these files: add a',
    "trace in a doc's front matter (`traces:`) or a tag in a test (`{ tag: '@AC-AUTH-02' }`), then run",
    '`npm run docs:build`.',
    '',
    '- One matrix per feature (requirement → design → API → test), linked below.',
    '- [tests.md](tests.md): the reverse view, test → requirement.',
    '',
    '## Coverage by feature',
    '',
    '| Feature | Phase | Criteria | High risk | Planned automated | With a tagged test | Automation gaps | Manual, unit or review | NFR |',
    '| ------- | ----- | -------- | --------- | ----------------- | ------------------ | --------------- | ---------------------- | --- |',
  ];
  for (const f of tracedFeatures()) {
    const acs = idsOfType('AC', f.code);
    out.push(
      `| [${f.title}](${f.dir}.md) | ${f.phase ?? '—'} | ${acs.length} | ${acs.filter((id) => col(id, 'Risk') === 'High').length} | ${acs.filter(isAutomated).length} | ${acs.filter((id) => testsFor.has(id)).length} | ${automationGaps(f).length} | ${acs.filter((id) => !isAutomated(id)).length} | ${idsOfType('NFR', f.code).length} |`,
    );
  }
  out.push(
    '',
    '## Gaps to review',
    '',
    '### High-risk criteria planned for automation without a test',
    '',
  );
  const highGaps = tracedFeatures()
    .flatMap(automationGaps)
    .filter((id) => col(id, 'Risk') === 'High');
  out.push(
    highGaps.length
      ? highGaps.map((id) => `- ${linkTo(rel, id)}: ${col(id, 'Then')}`).join('\n')
      : 'None.',
  );
  out.push('', '### Stories and rules without an acceptance criterion', '');
  const missing = tracedFeatures().flatMap(withoutCriterion);
  out.push(missing.length ? missing.map((id) => `- ${linkTo(rel, id)}`).join('\n') : 'None.');
  out.push('', '### Tests without a requirement tag', '');
  const untagged = untaggedTests();
  out.push(
    untagged.length
      ? untagged.map((t) => `- ${testRef(`${t.rel}:${t.line}`)} ${t.title}`).join('\n')
      : 'None.',
    '',
  );
  return out.join('\n');
}

function requirementsIndex() {
  const out = [
    GENERATED_NOTE,
    '',
    '# Requirements',
    '',
    'What the business needs, one folder per feature: stories (`US`), business rules (`BR`), acceptance criteria',
    '(`AC`) and messages (`MSG`). How to add a feature: [../\\_templates/README.md](../_templates/README.md).',
    'Coverage per criterion: [../traceability/](../traceability/README.md).',
    '',
    '| Feature | Phase | Status | Stories | Rules | Criteria | Criteria with a test |',
    '| ------- | ----- | ------ | ------- | ----- | -------- | -------------------- |',
  ];
  for (const f of features) {
    const acs = idsOfType('AC', f.code);
    out.push(
      `| [${f.title}](${f.dir}/README.md) | ${f.phase ?? '—'} | ${f.status} | ${idsOfType('US', f.code).length} | ${idsOfType('BR', f.code).length} | ${acs.length} | ${acs.filter((id) => testsFor.has(id)).length} |`,
    );
  }
  return out.join('\n') + '\n';
}

function decisionsIndex() {
  const out = [
    GENERATED_NOTE,
    '',
    '# Decisions',
    '',
    'One file per architecture decision (ADR). Phase 0 decisions D1–D13 are in the',
    '[Phase 0 architecture](../phases/phase-0-architecture.md). New one: copy [../\\_templates/adr.md](../_templates/adr.md).',
    '',
    '| ID | Decision | Status | Phase |',
    '| -- | -------- | ------ | ----- |',
  ];
  for (const id of idsOfType('ADR')) {
    const { doc } = defs.get(id);
    out.push(
      `| [${id}](${doc.rel.replace('decisions/', '')}) | ${doc.meta.title} | ${doc.meta.status} | ${doc.meta.phase ?? '—'} |`,
    );
  }
  return out.join('\n') + '\n';
}

if (errors.length === 0) {
  const outputs = {
    [GENERATED.requirements]: requirementsIndex(),
    [GENERATED.decisions]: decisionsIndex(),
    [`${TRACEABILITY_DIR}/README.md`]: traceabilityOverview(),
    [`${TRACEABILITY_DIR}/tests.md`]: traceabilityTests(),
  };
  for (const f of tracedFeatures()) outputs[featureFile(f)] = traceabilityFeature(f);
  await mkdir(join(DOCS, TRACEABILITY_DIR), { recursive: true });
  for (const name of await readdir(join(DOCS, TRACEABILITY_DIR))) {
    const rel = `${TRACEABILITY_DIR}/${name}`;
    if (outputs[rel]) continue;
    if (WRITE) {
      await rm(join(DOCS, rel));
      console.log(`removed docs/${rel}`);
    } else {
      errors.push(`docs/${rel} is no longer generated: run npm run docs:build`);
    }
  }
  for (const [rel, raw] of Object.entries(outputs)) {
    const path = join(DOCS, rel);
    const options = { ...(await prettier.resolveConfig(path)), filepath: path };
    const text = await prettier.format(raw, options);
    const current = await readFile(path, 'utf8').catch(() => '');
    if (current === text) continue;
    if (WRITE) {
      await writeFile(path, text);
      console.log(`updated docs/${rel}`);
    } else {
      errors.push(`docs/${rel} is out of date: run npm run docs:build`);
    }
  }
}

if (errors.length) {
  console.error(errors.map((e) => `✗ ${e}`).join('\n'));
  console.error(`\n${errors.length} problem(s) in the docs.`);
  process.exit(1);
}
const warnings = [
  ...tracedFeatures().flatMap((f) =>
    automationGaps(f).map(
      (id) => `${id} (${col(id, 'Risk')} risk) is planned for automation but has no tagged test`,
    ),
  ),
  ...tracedFeatures()
    .flatMap(withoutCriterion)
    .map((id) => `${id} has no acceptance criterion`),
  ...untaggedTests().map((t) => `${t.rel}:${t.line} "${t.title}" has no requirement tag`),
];
if (warnings.length) {
  console.warn(`${warnings.length} traceability gap(s), listed in docs/traceability/:`);
  console.warn(warnings.map((w) => `  ! ${w}`).join('\n'));
}
console.log(`✓ docs OK: ${defs.size} IDs, ${[...testsFor.values()].flat().length} test tags.`);
